mapper.select:
SELECT s.stock_code AS stockCode, s.stock_name AS stockName, s.market, s.industry, s.pe, s.pb, s.total_market_cap AS totalMarketCap, d.close_price AS price, d.change_percent AS changePct, d.volume, d.trade_date AS tradeDate FROM stock s LEFT JOIN stock_daily d ON s.stock_code = d.stock_code AND d.trade_date = (SELECT MAX(trade_date) FROM stock_daily)
AND (s.stock_name LIKE CONCAT('%',#{keyword},'%') OR s.stock_code LIKE CONCAT('%',#{keyword},'%')) AND s.industry = #{industry}
ORDER BY d.change_percent DESC LIMIT #{limit} OFFSET #{offset}
